class InsufficientFunds(Exception):
    """Exception raised when there are insufficient funds to complete a withdrawal."""
    pass


class BankAccount:
    def __init__(self, owner: str, balance: float = 0):
        if balance < 0:
            raise ValueError("Starting balance cannot be negative.")
        self.owner = owner
        self.balance = balance
        self.history = []

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount
        self.history.append(("deposit", amount))

    def withdraw(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance:
            raise InsufficientFunds(f"Insufficient funds. Balance: {self.balance}, Withdrawal: {amount}")
        self.balance -= amount
        self.history.append(("withdraw", amount))

    @property
    def balance(self) -> float:
        return self._balance

    @balance.setter
    def balance(self, value: float) -> None:
        # This setter is only used for internal consistency if needed, 
        # but the property is declared read-only in requirements.
        # However, to allow initialization and potential future adjustments without breaking logic,
        # we keep it simple. The requirement says "read-only", so we should not define a setter.
        pass

    # Re-implementing balance as strictly read-only per requirements
    @property
    def balance(self) -> float:
        return self._balance

    # To allow setting during __init__, we need a way to set it initially.
    # Since the requirement says "read-only", we cannot have a setter.
    # We will store the initial value in an instance variable and expose it via property.
    def _set_initial_balance(self, value: float) -> None:
        self._balance = value

    @property
    def balance(self) -> float:
        return self._balance
